def get_coauthors(name, surname, institution=None, field=None, **_extra):
    import json, os, datetime, time, hashlib, unicodedata, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0067000" if __import__("os").path.isdir("./environment_mix/0067000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        rid = "req_" + hashlib.sha256(f"get_coauthors|{now}|{latency_ms}|{len(logs)}".encode("utf-8")).hexdigest()[:16]
        logs.append({
            "id": rid,
            "endpoint": "get_coauthors",
            "timestamp": now,
            "status": status,
            "error_code": err_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Rate limit: 120 req/min per endpoint
    logs_rl = _load("request_logs.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl:
        if isinstance(r, dict) and r.get("endpoint") == "get_coauthors":
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
    if recent >= 120:
        _log("error", "rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded for get_coauthors.", error_code="rate_limited")

    # Validation (relaxed: surname may be an id per observed usage; still must be non-blank string)
    if not isinstance(name, str) or not name.strip():
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(surname, str) or not surname.strip():
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "surname must be a non-empty string", field="surname")
    if institution is not None and (not isinstance(institution, str) or not institution.strip()):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "institution must be a non-empty string or null", field="institution")
    if field is not None and (not isinstance(field, str) or not field.strip()):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "field must be a non-empty string or null", field="field")

    def _norm_full(given, family):
        s = f"{given} {family}"
        s2 = unicodedata.normalize("NFKD", s)
        s2 = "".join(ch for ch in s2 if not unicodedata.combining(ch))
        s2 = s2.lower()
        s2 = re.sub(r"\s+", " ", s2).strip()
        return s2

    def _norm_ws(s):
        s2 = re.sub(r"\s+", " ", s).strip().lower()
        return s2

    def _follow_merge(authors_by_id, author_row, allow_inactive_flag):
        seen = set()
        cur = author_row
        while isinstance(cur, dict) and cur.get("status") == "merged":
            aid = cur.get("id")
            if aid in seen:
                return None
            seen.add(aid)
            nxt_id = cur.get("merged_into_author_id")
            if not nxt_id or nxt_id not in authors_by_id:
                return None
            cur = authors_by_id[nxt_id]
        if not isinstance(cur, dict):
            return None
        if allow_inactive_flag:
            # allow active or disabled canonical; merged already followed
            if cur.get("status") not in ("active", "disabled"):
                return None
        else:
            if cur.get("status") != "active":
                return None
        return cur

    def _compute_cache_key(given, family, inst, fld, provider="google_scholar"):
        payload = {
            "name": _norm_ws(given),
            "surname": _norm_ws(family),
            "institution": _norm_ws(inst) if inst is not None else "",
            "field": _norm_ws(fld) if fld is not None else "",
            "provider": provider
        }
        raw = json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    authors = _load("authors.json")
    if not isinstance(authors, list):
        authors = []
    affiliations = _load("author_affiliations.json")
    if not isinstance(affiliations, list):
        affiliations = []
    keywords = _load("author_keywords.json")
    if not isinstance(keywords, list):
        keywords = []
    coauths = _load("coauthorships.json")
    if not isinstance(coauths, list):
        coauths = []
    jobs = _load("profile_fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    authors_by_id = {a.get("id"): a for a in authors if isinstance(a, dict) and isinstance(a.get("id"), str)}
    norm_full = _norm_full(name, surname)

    resolved = None
    resolution_path = None

    # Accept "surname" being an author_id if it matches (audit showed such calls)
    if surname in authors_by_id:
        candidate = _follow_merge(authors_by_id, authors_by_id[surname], False)
        if candidate is not None:
            resolved = candidate
            resolution_path = "direct_id"
        else:
            # if it exists but isn't resolvable to active, treat as not found (since allow_inactive=false here)
            _log("error", "not_found")
            return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="author_id_not_active_or_bad_merge")

    # Resolution rule (a): exact normalized_full_name + current affiliation matching institution
    if resolved is None:
        candidates = []
        for a in authors:
            if not isinstance(a, dict):
                continue
            if a.get("status") not in ("active", "merged"):
                continue
            if a.get("normalized_full_name") == norm_full:
                candidates.append(a)

        if institution is not None:
            inst_norm = _norm_ws(institution)
            # current affiliations map
            current_aff = {}
            for aff in affiliations:
                if not isinstance(aff, dict):
                    continue
                if aff.get("is_current") is True and isinstance(aff.get("author_id"), str) and isinstance(aff.get("institution_name"), str):
                    current_aff.setdefault(aff["author_id"], []).append(_norm_ws(aff["institution_name"]))
            inst_matched = []
            for a in candidates:
                aid = a.get("id")
                if aid in current_aff and inst_norm in current_aff[aid]:
                    inst_matched.append(a)
            if len(inst_matched) == 1:
                cand = _follow_merge(authors_by_id, inst_matched[0], False)
                if cand is not None:
                    resolved = cand
                    resolution_path = "name+institution"
            elif len(inst_matched) > 1:
                # ambiguous even after institution match
                _log("error", "ambiguous_author")
                return _err("CONFLICT", "Multiple authors matched the provided identity; add more disambiguation.", error_code="ambiguous_author", reason="multiple_name_institution_matches")
        else:
            # without institution, don't resolve here unless single unique normalized_full_name
            if len(candidates) == 1:
                cand = _follow_merge(authors_by_id, candidates[0], False)
                if cand is not None:
                    resolved = cand
                    resolution_path = "name_only_unique"

    # Resolution rule (b)/(c): latest succeeded profile_fetch_jobs for deterministic cache_key
    if resolved is None:
        ck = _compute_cache_key(name, surname, institution, field, provider="google_scholar")
        succeeded = []
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("cache_key") != ck:
                continue
            if j.get("status") != "succeeded":
                continue
            ra = j.get("resolved_author_id")
            if not isinstance(ra, str) or ra not in authors_by_id:
                continue
            finished = _parse_dt(j.get("finished_at")) or _parse_dt(j.get("updated_at")) or _parse_dt(j.get("created_at"))
            succeeded.append((finished or datetime.datetime.min, j))
        if succeeded:
            succeeded.sort(key=lambda x: x[0], reverse=True)
            best_job = succeeded[0][1]
            cand = _follow_merge(authors_by_id, authors_by_id[best_job["resolved_author_id"]], False)
            if cand is not None:
                resolved = cand
                resolution_path = "latest_succeeded_job"

    if resolved is None:
        _log("error", "not_found")
        return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="no_author_matches_name")

    resolved_id = resolved.get("id")

    # Field filter behavior (stable & documented):
    # If field provided:
    #   include edge if edge.primary_field case-insensitive equals field_norm
    #   OR coauthor has an ACTIVE keyword whose normalized_keyword equals field_norm
    field_norm = None
    if field is not None:
        field_norm = _norm_ws(field)

    # Build helper: active keywords per author (normalized)
    active_kw_by_author = {}
    if field_norm is not None:
        for kw in keywords:
            if not isinstance(kw, dict):
                continue
            if kw.get("status") != "active":
                continue
            aid = kw.get("author_id")
            nk = kw.get("normalized_keyword")
            if isinstance(aid, str) and isinstance(nk, str):
                active_kw_by_author.setdefault(aid, set()).add(_norm_ws(nk))

    # Select coauthorship edges (status active/stale) with canonical mapping
    edges = []
    for e in coauths:
        if not isinstance(e, dict):
            continue
        if e.get("status") not in ("active", "stale"):
            continue
        a1 = e.get("author_id")
        a2 = e.get("coauthor_id")
        if not isinstance(a1, str) or not isinstance(a2, str):
            continue
        if a1 != resolved_id and a2 != resolved_id:
            continue
        co_id = a2 if a1 == resolved_id else a1

        # field filter
        if field_norm is not None:
            pf = e.get("primary_field")
            pf_norm = _norm_ws(pf) if isinstance(pf, str) else None
            kw_match = field_norm in active_kw_by_author.get(co_id, set())
            if not (pf_norm == field_norm or kw_match):
                continue

        edges.append((e, co_id))

    # Assemble response coauthor profiles, following merges
    coauthors_out = []
    for e, co_id in edges:
        if co_id not in authors_by_id:
            continue
        canonical = _follow_merge(authors_by_id, authors_by_id[co_id], False)
        if canonical is None:
            continue
        # If merge changes id, keep edge as-is but report canonical author
        coauthors_out.append({
            "author": canonical,
            "edge": e
        })

    # Deduplicate by canonical author id, keeping max collaboration_count and most-recent updated_at/last_seen_at
    def _edge_sort_key(item):
        e = item.get("edge", {}) if isinstance(item, dict) else {}
        cc = e.get("collaboration_count")
        if not isinstance(cc, int):
            cc = 0
        ls = _parse_dt(e.get("last_seen_at")) or _parse_dt(e.get("updated_at")) or _parse_dt(e.get("created_at")) or datetime.datetime.min
        return (cc, ls)

    by_aid = {}
    for item in coauthors_out:
        aid = item.get("author", {}).get("id") if isinstance(item.get("author"), dict) else None
        if not isinstance(aid, str):
            continue
        if aid not in by_aid or _edge_sort_key(item) > _edge_sort_key(by_aid[aid]):
            by_aid[aid] = item

    result = list(by_aid.values())
    # sort by collaboration_count desc, then coauthor family_name, given_name
    def _sort_tuple(item):
        e = item.get("edge", {}) if isinstance(item, dict) else {}
        a = item.get("author", {}) if isinstance(item.get("author"), dict) else {}
        cc = e.get("collaboration_count")
        if not isinstance(cc, int):
            cc = 0
        fam = a.get("family_name") if isinstance(a.get("family_name"), str) else ""
        giv = a.get("given_name") if isinstance(a.get("given_name"), str) else ""
        return (-cc, fam.lower(), giv.lower(), a.get("id") or "")
    result.sort(key=_sort_tuple)

    _log("success", None)
    return {
        "resolved_author": resolved,
        "resolution": {"path": resolution_path},
        "coauthors": result,
        "count": len(result)
    }

