            if len(candidates) == 1:
                cand = _follow_merge(authors_by_id, candidates[0])
                if cand is not None:
                    resolved = cand
                    resolution_path = "name_only_unique"

    # Rule (c): highest-confidence from latest succeeded job for cache_key (we use latest succeeded)
    if resolved is None:
        ck = _compute_cache_key(name, surname, institution, provider="google_scholar")
        succeeded = []
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("cache_key") != ck:
                continue
            if j.get("status") != "succeeded":
                continue
            ra = j.get("resolved_author_id")
            if not isinstance(ra, str) or ra not in authors_by_id:
