            succeeded.sort(key=lambda x: x[0], reverse=True)
            best_job = succeeded[0][1]
            cand = _follow_merge(authors_by_id, authors_by_id[best_job["resolved_author_id"]])
            if cand is not None:
                resolved = cand
                resolution_path = "latest_succeeded_job"

    if resolved is None:
        _log("error", "not_found")
        return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="no_author_matches_name")

    author_id = resolved.get("id")

    # Return only active keywords, dedupe by normalized_keyword
    active = []
    for kw in kws:
        if not isinstance(kw, dict):
            continue
        if kw.get("author_id") != author_id:
            continue
        if kw.get("status") != "active":
            continue
        if not isinstance(kw.get("normalized_keyword"), str):
            continue
        active.append(kw)

    # Deduplicate: keep most recently updated row per normalized_keyword
    by_norm = {}
    for kw in active:
        nk = _norm_ws(kw.get("normalized_keyword"))
        dt = _parse_dt(kw.get("updated_at")) or _parse_dt(kw.get("created_at")) or datetime.datetime.min
