    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        rid = "req_" + hashlib.sha256(f"resolve_author|{now}|{latency_ms}|{len(logs)}".encode("utf-8")).hexdigest()[:16]
        logs.append({
            "id": rid,
            "endpoint": "resolve_author",
            "timestamp": now,
            "status": status,
            "error_code": err_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Rate limit: 240 req/min
    logs_rl = _load("request_logs.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl:
        if isinstance(r, dict) and r.get("endpoint") == "resolve_author":
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
    if recent >= 240:
        _log("error", "rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded for resolve_author.", error_code="rate_limited")

    # Validation (relaxed for observed usage: surname may be an author id)
    if not isinstance(name, str) or not name.strip():
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(surname, str) or not surname.strip():
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "surname must be a non-empty string", field="surname")
    if institution is not None and (not isinstance(institution, str) or not institution.strip()):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "institution must be a non-empty string or null", field="institution")
    if field is not None and (not isinstance(field, str) or not field.strip()):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "field must be a non-empty string or null", field="field")
    if not isinstance(allow_inactive, bool):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "allow_inactive must be a boolean", field="allow_inactive")

    def _norm_full(given, family):
        s = f"{given} {family}"
        s2 = unicodedata.normalize("NFKD", s)
        s2 = "".join(ch for ch in s2 if not unicodedata.combining(ch))
        s2 = s2.lower()
        s2 = re.sub(r"\s+", " ", s2).strip()
        return s2

    def _norm_ws(s):
        return re.sub(r"\s+", " ", s).strip().lower()

    def _follow_merge(authors_by_id, author_row, allow_inactive_flag):
        seen = set()
        cur = author_row
        while isinstance(cur, dict) and cur.get("status") == "merged":
            aid = cur.get("id")
            if aid in seen:
                return None
            seen.add(aid)
            nxt_id = cur.get("merged_into_author_id")
            if not nxt_id or nxt_id not in authors_by_id:
                return None
            cur = authors_by_id[nxt_id]
        if not isinstance(cur, dict):
            return None
        if allow_inactive_flag:
            if cur.get("status") not in ("active", "disabled"):
                return None
        else:
            if cur.get("status") != "active":
                return None
        return cur

    def _compute_cache_key(given, family, inst, fld, provider="google_scholar"):
        payload = {
            "name": _norm_ws(given),
            "surname": _norm_ws(family),
            "institution": _norm_ws(inst) if inst is not None else "",
            "field": _norm_ws(fld) if fld is not None else "",
            "provider": provider
        }
        raw = json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    authors = _load("authors.json")
    if not isinstance(authors, list):
        authors = []
    affiliations = _load("author_affiliations.json")
    if not isinstance(affiliations, list):
        affiliations = []
    kws = _load("author_keywords.json")
    if not isinstance(kws, list):
        kws = []
    jobs = _load("profile_fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    authors_by_id = {a.get("id"): a for a in authors if isinstance(a, dict) and isinstance(a.get("id"), str)}
    norm_full = _norm_full(name, surname)
    inst_norm = _norm_ws(institution) if institution is not None else None
    field_norm = _norm_ws(field) if field is not None else None

    # 0) If surname is an author id, resolve directly
    if surname in authors_by_id:
        resolved = _follow_merge(authors_by_id, authors_by_id[surname], allow_inactive)
        if resolved is None:
            _log("error", "not_found")
            return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="author_id_not_resolvable")
        _log("success", None)
        return {"author": resolved, "resolution": {"path": "direct_id"}}

    # Candidate set by normalized_full_name (active/merged; or include disabled if allow_inactive)
    candidates = []
    for a in authors:
        if not isinstance(a, dict):
            continue
        st = a.get("status")
        if allow_inactive:
            if st not in ("active", "disabled", "merged"):
                continue
        else:
            if st not in ("active", "merged"):
                continue
        if a.get("normalized_full_name") == norm_full:
            candidates.append(a)

    if not candidates:
        _log("error", "not_found")
        return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="no_author_matches_name")

    # Apply institution disambiguation: exact match vs current affiliation
    if inst_norm is not None:
        current_aff = {}
        for aff in affiliations:
            if not isinstance(aff, dict):
                continue
            if aff.get("is_current") is True and isinstance(aff.get("author_id"), str) and isinstance(aff.get("institution_name"), str):
                current_aff.setdefault(aff["author_id"], []).append(_norm_ws(aff["institution_name"]))
        inst_matched = []
        for a in candidates:
            aid = a.get("id")
            if isinstance(aid, str) and inst_norm in current_aff.get(aid, []):
                inst_matched.append(a)
        if inst_matched:
            candidates = inst_matched

    # Optional field hint disambiguation (stable mapping):
    # keep candidate if candidate.primary_field equals field_norm OR candidate has an ACTIVE keyword normalized_keyword equals field_norm
    if field_norm is not None and candidates:
        active_kw = {}
        for kw in kws:
            if not isinstance(kw, dict):
                continue
            if kw.get("status") != "active":
                continue
            aid = kw.get("author_id")
            nk = kw.get("normalized_keyword")
            if isinstance(aid, str) and isinstance(nk, str):
                active_kw.setdefault(aid, set()).add(_norm_ws(nk))
        filtered = []
        for a in candidates:
            aid = a.get("id")
            pf = a.get("primary_field")
            pf_norm = _norm_ws(pf) if isinstance(pf, str) else None
            if pf_norm == field_norm or (isinstance(aid, str) and field_norm in active_kw.get(aid, set())):
                filtered.append(a)
        if filtered:
            candidates = filtered

    # If exactly one after deterministic filtering, follow merge and return
    if len(candidates) == 1:
        resolved = _follow_merge(authors_by_id, candidates[0], allow_inactive)
        if resolved is None:
            _log("error", "not_found")
            return _err("NOT_FOUND", "Author not found for provided identity.", error_code="not_found", reason="candidate_not_resolvable")
        _log("success", None)
        return {"author": resolved, "resolution": {"path": "filtered_unique"}}

    # Otherwise consult latest succeeded profile_fetch_job for cache_key as deterministic tie-breaker
    ck = _compute_cache_key(name, surname, institution, field, provider="google_scholar")
    succeeded = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("cache_key") != ck:
            continue
        if j.get("status") != "succeeded":
            continue
        ra = j.get("resolved_author_id")
        if not isinstance(ra, str) or ra not in authors_by_id:
            continue
        finished = _parse_dt(j.get("finished_at")) or _parse_dt(j.get("updated_at")) or _parse_dt(j.get("created_at"))
        succeeded.append((finished or datetime.datetime.min, j))
    if succeeded:
        succeeded.sort(key=lambda x: x[0], reverse=True)
        best_job = succeeded[0][1]
        resolved = _follow_merge(authors_by_id, authors_by_id[best_job["resolved_author_id"]], allow_inactive)
        if resolved is not None:
            _log("success", None)
            return {"author": resolved, "resolution": {"path": "latest_succeeded_job", "job_id": best_job.get("id")}}

    # Ambiguous after all deterministic methods
    _log("error", "ambiguous_author")
    return _err("CONFLICT", "Multiple authors matched the provided identity; add more disambiguation.",
                error_code="ambiguous_author", reason="multiple_candidates_remain", candidate_count=len(candidates))

def list_authors(q=None, given_name=None, family_name=None, institution=None, primary_field=None, google_scholar_profile_id=None, status=None, limit=50, cursor=None, order_by="updated_at_desc", **_extra):
    import json, os, datetime, time, hashlib, unicodedata, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0067000" if __import__("os").path.isdir("./environment_mix/0067000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = unicodedata.normalize("NFKD", s)
        s2 = "".join(ch for ch in s2 if not unicodedata.combining(ch))
        s2 = s2.lower()
        s2 = re.sub(r"\s+", " ", s2).strip()
        return s2

    def _norm_ws(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        return re.sub(r"\s+", " ", s).strip().lower()

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_s, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + hashlib.sha256(f"list_authors|{now}|{latency_ms}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": "list_authors",
            "timestamp": now,
            "status": status_s,
            "error_code": err_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Rate limit: 240 req/min
    logs_rl = _load("request_logs.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl:
        if isinstance(r, dict) and r.get("endpoint") == "list_authors":
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
    if recent >= 240:
        _log("error", "rate_limited")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=60)

    # Validate
    for s, fn in [(q, "q"), (given_name, "given_name"), (family_name, "family_name"), (institution, "institution"),
                 (primary_field, "primary_field"), (google_scholar_profile_id, "google_scholar_profile_id"),
                 (cursor, "cursor")]:
        if s is not None and not isinstance(s, str):
            _log("error", "validation_error")
            return _err("VALIDATION_ERROR", f"Parameter '{fn}' must be a string or null.", field=fn)
        if isinstance(s, str) and fn != "cursor" and s.strip() == "":
            _log("error", "validation_error")
            return _err("VALIDATION_ERROR", f"Parameter '{fn}' must be non-blank when provided.", field=fn)

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "merged", "disabled"):
            _log("error", "validation_error")
            return _err("VALIDATION_ERROR", "Parameter 'status' must be one of: active, merged, disabled (or null).", field="status")

    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be an integer between 1 and 200.", field="limit")

    if order_by not in ("updated_at_desc", "created_at_desc", "family_name_asc"):
        _log("error", "validation_error")
        return _err("VALIDATION_ERROR", "Parameter 'order_by' must be one of: updated_at_desc, created_at_desc, family_name_asc.", field="order_by")

    # Decode cursor
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("endpoint") != "list_authors":
                _log("error", "validation_error")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = payload.get("offset")
            if not isinstance(offset, int) or offset < 0:
                _log("error", "validation_error")
                return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
        except Exception:
            _log("error", "validation_error")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    authors = _load("authors.json")
    if not isinstance(authors, list):
        authors = []

    # Filters
    qn = _norm(q) if q is not None else None
    gn = _norm(given_name) if given_name is not None else None
    fn = _norm(family_name) if family_name is not None else None
    instn = _norm_ws(institution) if institution is not None else None
    pfn = _norm(primary_field) if primary_field is not None else None

    filtered = []
    for a in authors:
        if not isinstance(a, dict):
            continue
        if status is not None and a.get("status") != status:
            continue
        if google_scholar_profile_id is not None and a.get("google_scholar_profile_id") != google_scholar_profile_id:
            continue
        if gn is not None and _norm(a.get("given_name") or "") != gn:
            continue
        if fn is not None and _norm(a.get("family_name") or "") != fn:
            continue
        if instn is not None:
            pi = a.get("primary_institution")
            if not (isinstance(pi, str) and _norm_ws(pi) == instn):
                continue
        if pfn is not None:
            pfv = a.get("primary_field")
            if not (isinstance(pfv, str) and _norm(pfv) == pfn):
                continue
        if qn is not None:
            nfull = a.get("normalized_full_name")
            if not isinstance(nfull, str):
                continue
            # implementation-defined: substring match on normalized_full_name
            if qn not in _norm(nfull):
                continue
        filtered.append(a)

    total = len(filtered)

    # Sort
    if order_by == "updated_at_desc":
        filtered.sort(key=lambda a: (_parse_dt(a.get("updated_at")) or datetime.datetime.min, a.get("id") or ""), reverse=True)
    elif order_by == "created_at_desc":
        filtered.sort(key=lambda a: (_parse_dt(a.get("created_at")) or datetime.datetime.min, a.get("id") or ""), reverse=True)
    else:  # family_name_asc
        filtered.sort(key=lambda a: (_norm(a.get("family_name") or ""), _norm(a.get("given_name") or ""), a.get("id") or ""))

    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "endpoint": "list_authors", "offset": next_offset, "order_by": order_by}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    _log("ok", None)
    return {
        "authors": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "order_by": order_by
        }
    }

def get_author(id, follow_merges=True, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0067000" if __import__("os").path.isdir("./environment_mix/0067000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    endpoint = "get_author"
    status = "success"

    try:
        if not isinstance(id, str) or not id.strip():
            status = "error"
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        if follow_merges is None:
            follow_merges = True
        if not isinstance(follow_merges, bool):
            status = "error"
            return _err("VALIDATION_ERROR", "follow_merges must be a boolean", field="follow_merges")

        authors = _load("authors.json")
        by_id = {a.get("id"): a for a in authors if isinstance(a, dict) and isinstance(a.get("id"), str)}

        if id not in by_id:
            status = "error"
            return _err("NOT_FOUND", "author not found", id=id)

        row = by_id[id]

        if follow_merges:
            # Follow merge chain to canonical author (must terminate; protect against cycles)
            seen = set()
            cur = row
            while isinstance(cur, dict) and cur.get("status") == "merged":
                if cur.get("id") in seen:
                    status = "error"
                    return _err("CONFLICT", "merge cycle detected", id=id)
                seen.add(cur.get("id"))
                target_id = cur.get("merged_into_author_id")
                if not isinstance(target_id, str) or not target_id.strip():
                    status = "error"
                    return _err("CONFLICT", "merged author missing merged_into_author_id", id=cur.get("id"))
                target = by_id.get(target_id)
                if not isinstance(target, dict):
                    status = "error"
                    return _err("CONFLICT", "merged_into_author_id references missing author", merged_into_author_id=target_id)
                cur = target
            row = cur

        return {"author": row}
    finally:
        # Request log (if collection exists)
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            end = datetime.datetime.utcnow()
            latency_ms = int((end - start).total_seconds() * 1000)
            logs.append({
                "id": "req_" + end.strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": None,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": end.isoformat(timespec="seconds") + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def create_profile_fetch_job(name, surname, provider, institution=None, field=None, reuse_if_fresh=True, force_refresh=False, **_extra):
    import json, os, datetime, hashlib, unicodedata, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0067000" if __import__("os").path.isdir("./environment_mix/0067000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    endpoint = "create_profile_fetch_job"
    status = "success"

    def _is_blank(s):
        return s is None or (isinstance(s, str) and s.strip() == "")

    def _norm_text(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            return None
        t = unicodedata.normalize("NFKD", s)
        t = "".join(ch for ch in t if not unicodedata.combining(ch))
        t = t.lower()
        t = re.sub(r"\s+", " ", t).strip()
        return t

    def _now_iso(dt):
        return dt.isoformat(timespec="seconds") + "Z"

    try:
        # Validate
        if not isinstance(name, str) or not name.strip():
            status = "error"
            return _err("VALIDATION_ERROR", "name must be a non-blank string", field="name")
        if not isinstance(surname, str) or not surname.strip():
            status = "error"
            return _err("VALIDATION_ERROR", "surname must be a non-blank string", field="surname")
        if provider != "google_scholar":
            status = "error"
            return _err("VALIDATION_ERROR", "unsupported provider", field="provider", allowed=["google_scholar"])
        if institution is not None and not isinstance(institution, str):
            status = "error"
            return _err("VALIDATION_ERROR", "institution must be a string or null", field="institution")
        if field is not None and not isinstance(field, str):
            status = "error"
            return _err("VALIDATION_ERROR", "field must be a string or null", field="field")
        if reuse_if_fresh is None:
            reuse_if_fresh = True
        if not isinstance(reuse_if_fresh, bool):
            status = "error"
            return _err("VALIDATION_ERROR", "reuse_if_fresh must be a boolean", field="reuse_if_fresh")
        if force_refresh is None:
            force_refresh = False
        if not isinstance(force_refresh, bool):
            status = "error"
            return _err("VALIDATION_ERROR", "force_refresh must be a boolean", field="force_refresh")

        n_name = _norm_text(name)
        n_surname = _norm_text(surname)
        n_inst = _norm_text(institution) if institution is not None else ""
        n_field = _norm_text(field) if field is not None else ""

        if n_name is None or n_surname is None or (institution is not None and n_inst is None) or (field is not None and n_field is None):
            status = "error"
            return _err("VALIDATION_ERROR", "invalid text input type")

        # cache_key: deterministic sha256 of normalized inputs + provider
        key_material = "|".join([provider, n_name, n_surname, n_inst, n_field]).encode("utf-8")
        cache_key = hashlib.sha256(key_material).hexdigest()

        jobs = _load("profile_fetch_jobs.json")
        if not isinstance(jobs, list):
            jobs = []

        # Rate limit / quota via request_logs if present (simple, stable):
        # - RATE_LIMIT: max 30 create_profile_fetch_job calls in last 60 seconds
        # - QUOTA_EXCEEDED: max 1000 create_profile_fetch_job calls in last 30 days
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                now = datetime.datetime.utcnow()
                def _parse(ts):
                    if not isinstance(ts, str):
                        return None
                    t = ts.rstrip("Z")
                    try:
                        return datetime.datetime.fromisoformat(t)
                    except Exception:
                        return None
                recent_60 = 0
                recent_30d = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    dt = _parse(r.get("created_at"))
                    if dt is None:
                        continue
                    delta = (now - dt).total_seconds()
                    if 0 <= delta <= 60:
                        recent_60 += 1
                    if 0 <= delta <= 30 * 24 * 3600:
                        recent_30d += 1
                if recent_60 >= 30:
                    status = "error"
                    return _err("RATE_LIMIT", "too many requests; try again later")
                if recent_30d >= 1000:
                    status = "error"
                    return _err("QUOTA_EXCEEDED", "monthly quota exceeded")
        except Exception:
            pass

        # Find existing job by unique cache_key
        existing = None
        for j in jobs:
            if isinstance(j, dict) and j.get("cache_key") == cache_key:
                existing = j
                break

        now = datetime.datetime.utcnow()

        def _is_unexpired_succeeded(j):
            if not isinstance(j, dict):
                return False
            if j.get("status") != "succeeded":
                return False
            exp = j.get("expires_at")
            if not isinstance(exp, str):
                return False
            try:
                exp_dt = datetime.datetime.fromisoformat(exp.rstrip("Z"))
            except Exception:
                return False
            return exp_dt > now

        # Reuse if fresh and allowed, unless force_refresh
        if existing is not None and reuse_if_fresh and (not force_refresh) and _is_unexpired_succeeded(existing):
            return {"job": existing, "reused": True}

        # If cache_key exists but isn't reusable, dedupe by updating it to queued (legal transitions enforced)
        if existing is not None:
            transitions = {
                "queued": ["running", "cancelled"],
                "running": ["succeeded", "failed", "cancelled"],
                "succeeded": [],
                "failed": ["queued"],
                "cancelled": ["queued"],
            }
            cur = existing.get("status")
            if cur not in transitions:
                status = "error"
                return _err("CONFLICT", "job has invalid status in store", id=existing.get("id"))
            if "queued" not in transitions.get(cur, []):
                # Can't move succeeded->queued; must create new job, but unique(cache_key) blocks.
                # Real backend would either create a new cache_key variant or keep succeeded; here, refresh by setting expires_at to past.
                if cur == "succeeded":
                    # expire it and then allow caller to create a new job by updating the same row to queued? still illegal transition.
                    status = "error"
                    return _err("INVALID_TRANSITION", "cannot re-queue a succeeded job; use force_refresh with a different input or wait for expiry", from_status=cur, to_status="queued")
                status = "error"
                return _err("INVALID_TRANSITION", "cannot re-queue job from current status", from_status=cur, to_status="queued")

            # Transition to queued and clear outcome fields
            existing["status"] = "queued"
            existing["error_code"] = None
            existing["error_message"] = None
            existing["started_at"] = None
            existing["finished_at"] = None
            existing["resolved_author_id"] = None

            # Set new expiry window (24h) from now; must be > created_at per constraint,
            # but created_at is historical; keep it, update expires_at and updated_at.
            existing["expires_at"] = _now_iso(now + datetime.timedelta(hours=24))
            existing["updated_at"] = _now_iso(now)
            _save("profile_fetch_jobs.json", jobs)
            return {"job": existing, "reused": False}

        # Create new job (unique(cache_key))
        job_id = "pfj_" + now.strftime("%Y%m%d%H%M%S%f")
        job = {
            "id": job_id,
            "query_given_name": name,
            "query_family_name": surname,
            "query_institution": institution,
            "query_field": field,
            "resolved_author_id": None,
            "status": "queued",
            "provider": provider,
            "cache_key": cache_key,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "expires_at": _now_iso(now + datetime.timedelta(hours=24)),
            "created_at": _now_iso(now),
            "updated_at": _now_iso(now),
        }
        jobs.append(job)
        _save("profile_fetch_jobs.json", jobs)
        return {"job": job, "reused": False}
    finally:
        # Request log (if collection exists)
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            end = datetime.datetime.utcnow()
            latency_ms = int((end - start).total_seconds() * 1000)
            logs.append({
                "id": "req_" + end.strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "credential_id": None,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": end.isoformat(timespec="seconds") + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def get_profile_fetch_job(id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0067000" if __import__("os").path.isdir("./environment_mix/0067000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, err_code=None, http_status=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        rid_src = f"get_profile_fetch_job|{now}|{latency_ms}|{len(logs)}|{id}"
        rid = "req_" + hashlib.sha256(rid_src.encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "endpoint": "get_profile_fetch_job",
            "timestamp": now,
            "status": status,
            "error_code": err_code,
            "latency_ms": latency_ms,
        }
        if http_status is not None:
            row["http_status"] = http_status
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limit: 240 req/min per endpoint (best-effort with request_logs)
    logs_rl = _load("request_logs.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "get_profile_fetch_job":
            continue
        ts = _parse_dt(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= 240:
        _log("error", "rate_limited", http_status=429)
        return _err("RATE_LIMIT", "Rate limit exceeded for get_profile_fetch_job.", error_code="rate_limited")

    if not isinstance(id, str) or not id.strip():
        _log("error", "validation_error", http_status=400)
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    # Accept any string id and try to resolve:
    # - first, as a profile_fetch_jobs.id
    # - if not found, as an authors.id to return the latest job that resolved to that author (common caller mistake)
    jobs = _load("profile_fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == id:
            job = r
            break

    if job is None:
        # Fallback: if caller passed an author id, map to latest job for that author
        candidates = []
        for r in jobs:
            if not isinstance(r, dict):
                continue
            if r.get("resolved_author_id") != id:
                continue
            candidates.append(r)

        def _job_sort_key(r):
            # Prefer updated_at, then created_at, then finished_at, then started_at
            for k in ("updated_at", "created_at", "finished_at", "started_at"):
                dt = _parse_dt(r.get(k))
                if dt:
                    return dt
            return datetime.datetime.min

        if candidates:
            candidates.sort(key=_job_sort_key, reverse=True)
            job = candidates[0]

    if job is None:
        _log("error", "not_found", http_status=404)
        return _err(
            "NOT_FOUND",
            "profile fetch job not found",
            error_code="not_found",
            id=id,
        )

    _log("ok", None, http_status=200)
    return {
        "profile_fetch_job": job,
    }
